<script lang="ts">
// Generated by the benchmark scripts; only docvia's own numbers, no comparisons.
import runtime from "#lib/benchmarks/runtime.json";
import setup from "#lib/benchmarks/setup.json";

const time = (ms: number) =>
	ms >= 1000 ? `${(ms / 1000).toFixed(1)} s` : `${Math.round(ms)} ms`;

const pages = Math.max(...runtime.rows.map((r) => r.pages));
const atScale = runtime.rows.filter((r) => r.pages === pages);

const machine = (m: typeof setup.machine) =>
	`${m.cpu}, ${m.cores} threads, ${m.ramGB} GB RAM, Node ${m.node.replace(/^v/, "")} on ${m.os === "win32" ? "Windows" : m.os}`;
</script>

<section id="benchmarks" class="scroll-mt-20 border-b border-hairline bg-canvas">
	<div class="mx-auto max-w-page px-5 py-14 sm:px-10 sm:py-24">
		<div class="mb-12 text-center">
			<span class="label-meta">Benchmarks</span>
			<h2
				class="mx-auto mt-4 max-w-2xl text-balance font-display text-[32px] leading-[1.05] tracking-tight text-ink sm:text-[48px] sm:leading-none"
			>
				What it costs to add docs.
			</h2>
			<p class="mx-auto mt-5 max-w-xl text-[15px] leading-relaxed text-muted">
				A fresh app from each framework's own CLI, then
				<code class="font-mono text-[13.5px] text-ink">docvia init --yes</code>.
				Nothing edited by hand.
			</p>
		</div>

		<div class="overflow-x-auto rounded-lg border border-hairline">
			<table class="w-full min-w-[720px] text-left text-[14px]">
				<thead class="border-b border-hairline bg-surface-soft text-[12px] text-muted">
					<tr>
						<th class="px-4 py-3 font-medium">Framework</th>
						<th class="px-4 py-3 font-medium">docvia init</th>
						<th class="px-4 py-3 font-medium">Files added or updated</th>
						<th class="px-4 py-3 font-medium">Hand edits</th>
						<th class="px-4 py-3 font-medium">/docs first compile</th>
						<th class="px-4 py-3 font-medium">Edit visible</th>
						<th class="px-4 py-3 font-medium">New page visible</th>
						<th class="px-4 py-3 font-medium">Build time added</th>
					</tr>
				</thead>
				<tbody class="divide-y divide-hairline font-mono tabular-nums text-ink">
					{#each setup.frameworks as row (row.framework)}
						<tr>
							<td class="px-4 py-3 font-sans">
								{row.framework}
								<span class="text-[12px] text-muted">{row.version}</span>
							</td>
							<td class="px-4 py-3">
								{time(row.initMs)}
								<span class="block text-[11px] text-muted">
									{time(row.installMs)} of it installing
								</span>
							</td>
							<td class="px-4 py-3">{row.files}</td>
							<td class="px-4 py-3">{row.manualEdits}</td>
							<td class="px-4 py-3">{time(row.docsFirstMs)}</td>
							<td class="px-4 py-3">{time(row.editMs)}</td>
							<td class="px-4 py-3">{time(row.addMs)}</td>
							<td class="px-4 py-3">
								+{time(Math.max(0, row.buildDocsMs - row.buildBaseMs))}
							</td>
						</tr>
					{/each}
				</tbody>
			</table>
		</div>
		<p class="mt-3 text-[12px] text-muted">
			Timings run after the stock app is warm, so they show what docs add. Measured
			{setup.date} on {machine(setup.machine)}.
		</p>

		<h3 class="mt-16 text-[20px] font-medium tracking-tight text-ink">
			At {pages.toLocaleString("en")} pages
		</h3>
		<div class="mt-4 overflow-x-auto rounded-lg border border-hairline">
			<table class="w-full min-w-[640px] text-left text-[14px]">
				<thead class="border-b border-hairline bg-surface-soft text-[12px] text-muted">
					<tr>
						<th class="px-4 py-3 font-medium">Renderer</th>
						<th class="px-4 py-3 font-medium">Dev server ready</th>
						<th class="px-4 py-3 font-medium">Edit visible</th>
						<th class="px-4 py-3 font-medium">Production build</th>
						<th class="px-4 py-3 font-medium">SSR cold import</th>
						<th class="px-4 py-3 font-medium">Server heap</th>
					</tr>
				</thead>
				<tbody class="divide-y divide-hairline font-mono tabular-nums text-ink">
					{#each atScale as row (row.renderer)}
						<tr>
							<td class="px-4 py-3 font-sans">{row.renderer}</td>
