						</tr>
					{/each}
				</tbody>
			</table>
		</div>
		<p class="mt-3 text-[12px] text-muted">
			Vite 8, generated pages with code blocks and tables. Page bodies load lazily, so
			a cold server import stays small as docs grow. Best of {runtime.runs} runs,
			{runtime.date}, {machine(runtime.machine)}.
		</p>
	</div>
</section>
